import java.io.IOException;
import java.util.*;
import java.io.*;
public class ll {
    public static void main(String[] args) throws IOException {
        gg g = new gg();
    }

}
class gg {
    gg() throws IOException {
        FScanner fs = new FScanner(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = fs.nextInt();
        char[] word = fs.nextLine().toCharArray();
        int[] vals = fs.iarr(n);
        int[] badones = new int[26];
        int m = 0;
        for (int i = 0; i<n/2; i++)
            if (word[i] == word[n-i-1])
            {
                badones[word[i]-'a']++;
                m++;
            }
        int max = 0;
        boolean bad = false;
        int val = -1;
        for (int i  = 0; i<26; i++)
            if (badones[i]*2>m)
            {
                bad = true;
                val = i;
            }
        if (!bad) {
            long sum = 0;
            for (int i = 0; i<n/2; i++)
                if (word[i] !=word[n-i-1])
                    sum+=vals[i]+vals[n-i-1];
                else sum+=Math.max(vals[i], vals[n-i-1]);
            pw.println(sum);
        } else {
            int others = badones[val]-(m-badones[val]);
            ArrayList<Integer> appr = new ArrayList<>();
            for (int i = 0; i<n/2; i++)
                if (word[i] != word[n-i-1] && word[i] != 'a'+val && word[n-i-1] != 'a'+val)
                    appr.add(Math.min(vals[i], vals[n-i-1]));
            appr.sort(null);
            long ans = 0;
            for (int i =0 ; i<n/2; i++) {
                if (word[i] == word[n-i-1])
                    ans+=Math.max(vals[i], vals[n-i-1]);
                else ans+=vals[i]+vals[n-i-1];
            }
            for (int i =0 ; i<others; i++)
                ans-=appr.get(i);
            pw.println(ans);
        }
        pw.close();
    }

    void add(long s, TreeMap<Long, Integer> map) {
        if (map.containsKey(s))
            map.put(s, map.get(s)+1);
        else map.put(s, 1);
    }
    long lowest(TreeMap<Long, Integer> map) {
        if (map.size() == 0)
            return -1;
        long v = map.firstKey();
        if (map.get(v) == 1) {
            map.remove(v);
        } else {
            map.put(v, map.get(v)-1);
        }
        return v;
    }

}


class FScanner {
    StringTokenizer st;
    BufferedReader reader;
    FScanner(InputStreamReader isr) throws IOException {
        reader = new BufferedReader(isr);
    }

    String nextLine() throws IOException {
        return reader.readLine();
    }

    String nextToken() throws IOException{
        while (st == null || !st.hasMoreTokens()) {
            String s = reader.readLine();
            if (s == null)
                return null;
            st = new StringTokenizer(s);
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    char nextChar() throws IOException {
        return (char) reader.read();
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    int[] iarr(int n) throws IOException {
        int[] mas = new int[n];
        for (int i =0 ; i<n; i++)
            mas[i] = nextInt();
        return mas;
    }

    double[] darr(int n) throws IOException {
        double[] mas = new double[n];
        for (int i =0 ; i<n; i++)
            mas[i] = nextDouble();
        return mas;
    }

    char[][] cmas2 (int n, int m) throws IOException {
        char[][] mas = new char[n][m];
        for (int i =0 ; i<n; i++)
            mas[i] = nextLine().toCharArray();
        return mas;
    }

    long[] larr(int n) throws IOException {
        long[] mas = new long[n];
        for (int i =0 ; i<n; i++)
            mas[i] = nextLong();
        return mas;
    }

}
